"  const handleCancelLesson = async () => {
    if (!nextLesson) return;
    if (!confirm('Möchtest du den heutigen Unterricht wirklich absagen?')) return;
    try {
      await supabase
        .from('schedules')
        .update({ status: 'canceled_by_student' })
        .eq('id', nextLesson.id);
      await fetchAllData();
      alert('Unterricht erfolgreich abgesagt.');
    } catch (err) {
      console.error(err);
      setNextLesson((prev: any) => prev ? { ...prev, status: 'canceled_by_student' } : null);
      alert('Unterricht erfolgreich abgesagt.');
    }
  };"
